1	<!doctype html>
2	<html lang="en" data-resolution="landscape">
3	  <head>
4	    <meta charset="UTF-8" />
5	    <meta name="viewport" content="width=1920, height=1080" />
6	    <title>Codely Reveal</title>
7	    <script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script>
8	    <link rel="preconnect" href="https://fonts.googleapis.com" />
9	    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
10	    <link
11	      href="https://fonts.googleapis.com/css2?family=Geist:wght@400;600;700;800;900&display=swap"
12	      rel="stylesheet"
13	    />
14	    <style>
15	      * {
16	        margin: 0;
17	        padding: 0;
18	        box-sizing: border-box;
19	      }
20	
21	      /* Transparent everywhere — this composition renders as an alpha overlay,
22	         composited on top of the existing webcam shot. No opaque background. */
23	      html,
24	      body {
25	        width: 1920px;
26	        height: 1080px;
27	        overflow: hidden;
28	        background: transparent;
29	      }
30	
31	      body {
32	        font-family: "Geist", "Inter", "Helvetica Neue", Arial, sans-serif;
33	      }
34	
35	      #root {
36	        position: relative;
37	        width: 1920px;
38	        height: 1080px;
39	        overflow: hidden;
40	        background: transparent;
41	      }
42	
43	      #scene {
44	        position: absolute;
45	        inset: 0;
46	      }
47	
48	      /* ---------- Ambient brand-color glow behind the card ---------- */
49	
50	      .glow-pos {
51	        position: absolute;
52	        left: 50%;
53	        top: 812px;
54	        transform: translate(-50%, -50%);
55	      }
56	
57	      #glow-motion {
58	        width: 980px;
59	        height: 480px;
60	        border-radius: 50%;
61	        background: radial-gradient(
62	          ellipse at center,
63	          rgba(255, 130, 170, 0.55) 0%,
64	          rgba(255, 150, 120, 0.38) 38%,
65	          rgba(210, 70, 190, 0.22) 62%,
66	          rgba(210, 70, 190, 0) 78%
67	        );
68	        filter: blur(46px);
69	        opacity: 0;
70	      }
71	
72	      /* ---------- Glass card ---------- */
73	
74	      .card-pos {
75	        position: absolute;
76	        left: 50%;
77	        top: 812px;
78	        transform: translate(-50%, -50%);
79	      }
80	
81	      #card-motion {
82	        position: relative;
83	        display: inline-flex;
84	        align-items: center;
85	        justify-content: center;
86	        padding: 54px 108px;
87	        border-radius: 64px;
88	        opacity: 0;
89	        background: linear-gradient(
90	          150deg,
91	          rgba(255, 255, 255, 0.26) 0%,
92	          rgba(255, 255, 255, 0.1) 46%,
93	          rgba(255, 255, 255, 0.16) 100%
94	        );
95	        -webkit-backdrop-filter: blur(28px) saturate(180%);
96	        backdrop-filter: blur(28px) saturate(180%);
97	        border: 1.5px solid rgba(255, 255, 255, 0.55);
98	        box-shadow:
99	          0 30px 70px rgba(20, 10, 25, 0.38),
100	          0 2px 0 rgba(255, 255, 255, 0.35) inset,
101	          0 -18px 30px rgba(120, 40, 90, 0.12) inset;
102	        overflow: hidden;
103	      }
104	
105	      /* subtle top light catch, the classic liquid-glass highlight */
106	      #card-motion::before {
107	        content: "";
108	        position: absolute;
109	        inset: 0;
110	        background: linear-gradient(
111	          180deg,
112	          rgba(255, 255, 255, 0.45) 0%,
113	          rgba(255, 255, 255, 0) 32%
114	        );
115	        pointer-events: none;
116	      }
117	
118	      /* one-shot diagonal sheen sweep */
119	      #sheen {
120	        position: absolute;
121	        top: -40%;
122	        left: -60%;
123	        width: 60%;
124	        height: 180%;
125	        background: linear-gradient(
126	          100deg,
127	          rgba(255, 255, 255, 0) 0%,
128	          rgba(255, 255, 255, 0.55) 50%,
129	          rgba(255, 255, 255, 0) 100%
130	        );
131	        transform: translateX(-120%) rotate(8deg);
132	        opacity: 0;
133	        pointer-events: none;
134	      }
135	
136	      /* ---------- Wordmark ---------- */
137	
138	      #wordmark {
139	        position: relative;
140	        font-family: "Geist", "Inter", sans-serif;
141	        font-weight: 800;
142	        font-size: 156px;
143	        line-height: 1;
144	        letter-spacing: -4px;
145	        white-space: nowrap;
146	        opacity: 0;
147	        background: linear-gradient(100deg, #ff7aa8 0%, #ffb37a 38%, #ff6fae 66%, #cf3fc4 100%);
148	        -webkit-background-clip: text;
149	        background-clip: text;
150	        color: transparent;
151	      }
152	    </style>
153	  </head>
154	  <body>
155	    <div
156	      id="root"
157	      data-composition-id="main"
158	      data-start="0"
159	      data-duration="3.2"
160	      data-width="1920"
161	      data-height="1080"
162	    >
163	      <div id="scene" class="clip" data-start="0" data-duration="3.2" data-track-index="1">
164	        <div class="glow-pos">
165	          <div id="glow-motion"></div>
166	        </div>
167	
168	        <div class="card-pos">
169	          <div id="card-motion" data-layout-allow-overflow>
170	            <div id="sheen"></div>
171	            <div id="wordmark">Codely</div>
172	          </div>
173	        </div>
174	      </div>
175	    </div>
176	
177	    <script>
178	      window.__timelines = window.__timelines || {};
179	      const tl = gsap.timeline({ paused: true });
180	
181	      // ---- Entrance (0 -> 1.18s): card lands, then wordmark punches in on top,
182	      // settling exactly as the source audio says "Codely" (source 341.04s). ----
183	
184	      // Ambient glow blooms in first, sets the color mood.
185	      tl.fromTo(
186	        "#glow-motion",
187	        { opacity: 0, scale: 0.82 },
188	        { opacity: 1, scale: 1, duration: 0.7, ease: "power2.out" },
189	        0
190	      );
191	
192	      // Glass card rises and settles — decisive ease-out cubic, no bounce.
193	      tl.fromTo(
194	        "#card-motion",
195	        { opacity: 0, scale: 0.84, y: 22 },
196	        { opacity: 1, scale: 1, y: 0, duration: 0.58, ease: "power2.out" },
197	        0.05
198	      );
199	
200	      // Wordmark punches in on top of the settled card, landing at 1.18s —
201	      // the exact instant the source audio hits "Codely".
202	      tl.fromTo(
203	        "#wordmark",
204	        { opacity: 0, scale: 1.22, y: 16 },
205	        { opacity: 1, scale: 1, y: 0, duration: 0.7, ease: "power2.out" },
206	        0.48
207	      );
208	
209	      // One-shot sheen sweep catches the light right as the wordmark lands.
210	      tl.fromTo(
211	        "#sheen",
212	        { opacity: 0, x: "-20%" },
213	        { opacity: 1, x: "260%", duration: 0.45, ease: "power2.inOut" },
214	        0.9
215	      );
216	      tl.to("#sheen", { opacity: 0, duration: 0.15, ease: "power1.out" }, 1.35);
217	
218	      // ---- Hold (1.18s -> 2.5s): settled, readable, ~1.3s while the line finishes. ----
219	
220	      // ---- Exit (2.6s -> 3.2s): clean fade + scale down before the slot ends. ----
221	
222	      tl.to(
223	        ["#card-motion", "#glow-motion"],
224	        { opacity: 0, scale: 0.94, y: -10, duration: 0.5, ease: "power2.in" },
225	        2.6
226	      );
227	      tl.to("#wordmark", { opacity: 0, scale: 0.94, y: -10, duration: 0.5, ease: "power2.in" }, 2.6);
228	
229	      window.__timelines["main"] = tl;
230	    </script>
231	  </body>
232	</html>
